from __future__ import unicode_literals

from functools import partial
import unittest
from ute_common_util.test.temp import path_to_resource
from ute_common_config_files.scfc.exceptions import NoSuchParameter, NoSuchListParameter, NoSuchManagedObject
from ute_common_config_files.scfc.scfc import Scfc

path_to_resource = partial(path_to_resource, __name__)
DIST_NAME = 'MRBTS-1/BTSSCL-1/LCELL-1'


class TestManagedObject(unittest.TestCase):

    @path_to_resource('resources/scfc/simple_param.xml')
    def test_find_param_by_name_found(self, scfc_path):
        managed_object = Scfc(scfc_path).find_managed_object(DIST_NAME)
        param = managed_object.find_param('existingParam')
        self.assertEqual(param.xml.tag, '{raml21.xsd}p')
        self.assertEqual(param.xml.get('name'), 'existingParam')

    @path_to_resource('resources/scfc/simple_param.xml')
    def test_find_param_by_name_not_found(self, scfc_path):
        managed_object = Scfc(scfc_path).find_managed_object(DIST_NAME)
        with self.assertRaises(NoSuchParameter):
            managed_object.find_param('notExistingParam')

    @path_to_resource('resources/scfc/simple_param_duplicated.xml')
    def test_find_param_by_name_and_value_found(self, scfc_path):
        managed_object = Scfc(scfc_path).find_managed_object(DIST_NAME)
        param = managed_object.find_param('existingParam', param_value='2')
        self.assertEqual(param.xml.tag, '{raml21.xsd}p')
        self.assertEqual(param.name, 'existingParam')
        self.assertEqual(param.xml.text, '2')

    @path_to_resource('resources/scfc/simple_param_duplicated.xml')
    def test_find_param_by_name_and_value_not_found(self, scfc_path):
        managed_object = Scfc(scfc_path).find_managed_object(DIST_NAME)
        with self.assertRaises(NoSuchParameter):
            managed_object.find_param('existingParam', param_value='3')
        with self.assertRaises(NoSuchParameter):
            managed_object.find_param('notExistingParam', param_value='2')

    @path_to_resource('resources/scfc/3_empty_lists.xml')
    def test_find_all_list_params(self, scfc_path):
        managed_object = Scfc(scfc_path).find_managed_object(DIST_NAME)
        list_params = managed_object.find_all_list_params()
        self.assertEqual(list_params[0].name, 'existingList')
        self.assertEqual(list_params[1].name, 'existingList2')
        self.assertEqual(list_params[2].name, 'existingList3')

    @path_to_resource('resources/scfc/complex_param.xml')
    def test_find_list_param_found(self, scfc_path):
        managed_object = Scfc(scfc_path).find_managed_object(DIST_NAME)
        list_param = managed_object.find_list_param('existingList')
        self.assertEqual(list_param.xml.tag, '{raml21.xsd}list')
        self.assertEqual(list_param.name, 'existingList')

    @path_to_resource('resources/scfc/complex_param.xml')
    def test_find_list_param_not_found(self, scfc_path):
        managed_object = Scfc(scfc_path).find_managed_object(DIST_NAME)
        with self.assertRaises(NoSuchListParameter):
            managed_object.find_list_param('notExistingList')

    @path_to_resource('resources/scfc/empty_managed_object.xml')
    def test_add_param_to_empty_managed_object(self, scfc_path):
        managed_object = Scfc(scfc_path).find_managed_object(DIST_NAME)
        added_param = managed_object.add_param('newParam', 'newValue')
        self.assertEqual(managed_object.find_param('newParam'), added_param)
        self.assertEqual(added_param.value, 'newValue')

    @path_to_resource('resources/scfc/empty_managed_object.xml')
    def test_add_duplicated_params(self, scfc_path):
        managed_object = Scfc(scfc_path).find_managed_object(DIST_NAME)
        added_param_1 = managed_object.add_param('newParam', 'newValue1', multiple=True)
        added_param_2 = managed_object.add_param('newParam', 'newValue2', multiple=True)
        self.assertEqual(managed_object.find_param('newParam', 'newValue1'), added_param_1)
        self.assertEqual(managed_object.find_param('newParam', 'newValue2'), added_param_2)
        self.assertEqual(added_param_1.value, 'newValue1')
        self.assertEqual(added_param_2.value, 'newValue2')

    @path_to_resource('resources/scfc/empty_managed_object.xml')
    def test_dist_name(self, scfc_path):
        managed_object = Scfc(scfc_path).find_managed_object(DIST_NAME)
        self.assertEqual(managed_object.dist_name, DIST_NAME)
        managed_object.dist_name = 'MRBTS-1/LCELL-69'
        self.assertEqual(managed_object.dist_name, 'MRBTS-1/LCELL-69')
        self.assertEqual(managed_object.id, 69)

    @path_to_resource('resources/scfc/3_empty_managed_objects.xml')
    def test_clone(self, scfc_path):
        scfc = Scfc(scfc_path)
        self.assertEqual(scfc.count_managed_objects('LCELL'), 3)
        orginal_lcell = scfc.find_managed_object('MRBTS-1/BTSSCL-1/LCELL-1')
        orginal_lcell.add_param("existingParam", 17)
        orginal_lcell.clone(new_id=4)
        self.assertEqual(scfc.count_managed_objects('LCELL'), 4)
        copied_lcell = scfc.find_managed_object('MRBTS-1/BTSSCL-1/LCELL-4')
        self.assertEqual(orginal_lcell.find_param('existingParam').value, copied_lcell.find_param('existingParam').value)

    @path_to_resource('resources/scfc/3_empty_managed_objects.xml')
    def test_clone_fail_with_kwargs(self, scfc_path):
        scfc = Scfc(scfc_path)
        self.assertEqual(scfc.count_managed_objects('LCELL'), 3)
        with self.assertRaises(NoSuchParameter):
            scfc.find_managed_object('MRBTS-1/BTSSCL-1/LCELL-1').clone(new_id=4, param1=1)

    @path_to_resource('resources/scfc/simple_param.xml')
    def test_clone_with_kwargs(self, scfc_path):
        scfc = Scfc(scfc_path)
        self.assertEqual(scfc.count_managed_objects('LCELL'), 1)
        self.assertEqual(scfc.find_single_managed_object('LCELL').find_param('existingParam').value, '123')
        scfc.find_managed_object('MRBTS-1/BTSSCL-1/LCELL-1').clone(new_id=4, existingParam=1)
        lcell = scfc.find_managed_object('MRBTS-1/BTSSCL-1/LCELL-4')
        self.assertEqual(scfc.count_managed_objects('LCELL'), 2)
        self.assertEqual(lcell.find_param('existingParam').value, '1')

    @path_to_resource('resources/scfc/3_empty_managed_objects.xml')
    def test_id(self, scfc_path):
        scfc = Scfc(scfc_path)
        lcell = scfc.find_managed_object('MRBTS-1/BTSSCL-1/LCELL-2')
        self.assertEqual(lcell.id, 2)
        lcell.id = 13
        self.assertEqual(lcell.dist_name, 'MRBTS-1/BTSSCL-1/LCELL-13')
        self.assertEqual(lcell.id, 13)
        with self.assertRaises(NoSuchManagedObject):
            scfc.find_managed_object('MRBTS-1/BTSSCL-1/LCELL-2')

    @path_to_resource('resources/scfc/test_SCFC.xml')
    def test_find_all_params(self, scfc_path):
        scfc = Scfc(scfc_path)
        all_params = scfc.find_managed_object('MRBTS-1/LNBTS-1/LBPUCCHRDPR-0').find_all_params()
        self.assertEqual([p.name for p in all_params], ["countdownPucchCompr", "countdownPucchExp",
                                                        "rrcConnectedLowerThresh", "rrcConnectedUpperThresh"])
